package com.example.techfix;
import android.os.*; import android.view.View; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.*; import com.example.techfix.ui.*; import java.util.*; import java.util.concurrent.*;
public class AdminActivity extends AppCompatActivity { private AppDatabase db; private RecyclerView recyclerView; private final ExecutorService executor=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper());
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_admin);db=AppDatabase.getDatabase(getApplicationContext());recyclerView=findViewById(R.id.rvAdminAppointments);recyclerView.setLayoutManager(new LinearLayoutManager(this));loadAppointments();}
 private void loadAppointments(){TextView empty=findViewById(R.id.tvAdminEmptyState);executor.execute(()->{List<Appointment> all=db.appointmentDao().getActiveAppointments();List<AdminAppointmentDisplay> displays=new ArrayList<>();for(Appointment a:all){User c=db.userDao().getUserById(a.getCustomerId());Branch br=db.branchDao().getBranchById(a.getBranchId());RepairService s=db.repairServiceDao().getServiceById(a.getServiceId());displays.add(new AdminAppointmentDisplay(a.getAppointmentId(),c==null?"Unknown Customer":c.getName(),s==null?"Unknown Service":s.getName(),br==null?"Unknown Branch":br.getName(),a.getRequestedDate(),a.getStatus()));}main.post(()->{if(displays.isEmpty()){empty.setVisibility(View.VISIBLE);return;}empty.setVisibility(View.GONE);recyclerView.setAdapter(new AdminAppointmentAdapter(displays,(a,status)->executor.execute(()->{db.appointmentDao().updateStatus(a.getAppointmentId(),status);main.post(()->{Toast.makeText(this,a.getCustomerName()+"'s appointment updated to "+status,Toast.LENGTH_SHORT).show();loadAppointments();});})));});});}
 @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}
}